package com.inridemart.order;
import java.math.BigDecimal; import java.time.Instant; import java.util.List; import java.util.UUID;
public record Order(UUID id, UUID userId, String idempotencyKey, OrderStatus status, List<OrderItem> items, BigDecimal totalAmount, String currency, Instant createdAt) { public static Order place(UUID userId, String key, List<OrderItem> items, Instant now) { if (items == null || items.isEmpty()) throw new IllegalArgumentException("Order must contain at least one item"); String currency = items.getFirst().currency(); if (items.stream().anyMatch(item -> !currency.equals(item.currency()))) throw new IllegalArgumentException("Order items must use one currency"); BigDecimal total = items.stream().map(OrderItem::lineTotal).reduce(BigDecimal.ZERO, BigDecimal::add); return new Order(UUID.randomUUID(), userId, key, OrderStatus.PLACED, List.copyOf(items), total, currency, now); } public Order withStatus(OrderStatus next) { return new Order(id, userId, idempotencyKey, next, items, totalAmount, currency, createdAt); } }
